sited.script:

// 核心的「內容列表」解析函式
function list_parse(url, jsontext) {
    try {
        const response = JSON.parse(jsontext);
        if (!response || !response.data || !Array.isArray(response.data.items)) {
            return JSON.stringify([]);
        }
        const list = response.data.items.map(item => ({
            logo: item.thumbnail.replace(/^http:/, 'https:'),
            name: gbk2big5.traditionalized(item.title),
            // API 回傳的 URL 可能是 http，手動換成 https 增加安全性
            url: item.url.replace(/^http:/, 'https:')
        }));
        return JSON.stringify(list);
    } catch (error) {
        return JSON.stringify([]);
    }
}

function search_parse_url(url, html) {
    var $ = cheerio.load(html);
    var urls = [];
    urls.push(url);

    // 將選擇結果存到變數中，避免重複查詢
    var prevLink = $('div.nav-previous a');

    // 正確的判斷方式：檢查集合的長度
    if (prevLink.length > 0) {
        // 直接在 Cheerio 物件上取得屬性
        urls.push("CALL::" + prevLink.attr('href'));
    }
    return JSON.stringify(urls);
}

// 解析文章詳情頁 (Book)，僅作導航用途
function book_parse(url, html) {
    const $ = cheerio.load(html);
    const name = $('meta[property="og:title"]').attr('content') || $('title').text();
    const logo = $('meta[property="og:image"]').attr('content');
    const sections = [{
        name: "閱讀全文",
        url: url.replace(/^http:/, 'https:')
    }];
    const book = {
        name: gbk2big5.traditionalized(name),
        logo: logo,
        intro: gbk2big5.traditionalized("點擊下方 '閱讀全文' 開始閱讀"),
        sections: sections
    };
    return JSON.stringify(book);
}

// ⭐【核心修正】解析文章內容頁 (Section)，僅處理圖文
function section_parse(url, html) {
    const $ = cheerio.load(html);
    const data = [];

    // 找到文章的主要容器
    const articleContent = $('article#article-detail-content');

    // 遍歷容器內的所有直接子元素 (<p>, <div> 等)
    // 這種結構下，內容通常都在一個 <p> 標籤內
    articleContent.children().each(function() {
        const container = $(this);

        // 處理容器內的所有節點，包括文字和 <br>
        container.contents().each(function() {
            const node = $(this);

            // 處理文字節點 (文字、<span>, <strong>, <a>)
            if (this.type === 'text' || (this.type === 'tag' && (node.is('span') || node.is('strong') || node.is('a')))) {
                const text = node.text().trim();
                if (text) {
                    let item = { t: "text", d: gbk2big5.traditionalized(text) };
                    if (node.is('strong') || node.find('strong').length > 0) {
                        item.b = 1; // 標記為粗體
                    }
                    data.push(item);
                }
            }
            // 處理圖片節點
            else if (this.type === 'tag' && node.is('img')) {
                let src = node.attr('src');
                if (src) {
                    if (src.startsWith('//')) {
                        src = 'https:' + src;
                    }
                    data.push({ t: "image", d: src });
                }
            }
            // 其他所有標籤 (如 iframe, br) 都會被忽略
        });
    });

    return JSON.stringify({type:"article", data: data});
}
